const fwrap = u => ((u % 1) + 1) % 1;
for (const F of Object.values(FIGC)) { F.cum = pathCum(F.hole); F.P = F.cum[F.cum.length - 1]; F.OP = pathCum(F.outer)[F.outer.length];
  F.cornersU = cornersOf(F.hole, F.cum, 0.3).map(c => c.s / F.P);
  F.A = Math.abs(signedArea(F.outer)) - Math.abs(signedArea(F.hole)); }
function figParts(k, n, u) {       // n = nodos de la caladura; el borde exterior con el mismo paso
  // tope de malla: unos 1300 vértices por cada 76 nodos de costura, para que una caladura chica no llene la lámina de triángulos
  const F = FIGC[k], hCap = Math.sqrt(F.A / (0.866 * 1300 * n / 76));
  n = Math.min(n, Math.max(24, Math.round(F.P / hCap)));
  const hole = boundaryFromA(F.hole, fwrap(u || 0) * F.P, n), h = F.P / hole.length;
  const outer = boundaryFromA(F.outer, 0, Math.max(24, Math.round(F.OP / h)));
  return { outer, hole };
}
function gotaParts(n) { return figParts('G', n, 0); }
