/* ── triángulo: A se ubica por u ∈ [0,1) = fracción del perímetro desde el vértice 1; B siempre en u + ½ ── */
function triCum(c) { const cum = [0]; for (let i = 0; i < 3; i++) { const a = c[i], b = c[(i + 1) % 3]; cum.push(cum[i] + Math.hypot(b[0] - a[0], b[1] - a[1])); } return cum; }
