// puntos de curvatura del cierre completo (ángulo de cono ≠ 2π)
// centros de los tres cierres (punto medio de cada arista), en longitud de arco desde el punto medio de la arista 1
function triCenters(c) {
  const L = [0, 1, 2].map(i => Math.hypot(c[(i + 1) % 3][0] - c[i][0], c[(i + 1) % 3][1] - c[i][1]));
  return [{ s0: 0, ext: L[0] / 2 }, { s0: L[0] / 2 + L[1] / 2, ext: L[1] / 2 }, { s0: L[0] / 2 + L[1] + L[2] / 2, ext: L[2] / 2 }];
}
function conePoints(c, u) {
  const cum = triCum(c), P = cum[3], sA = wrap(u) * P, tol = 1e-3 * P;
  const sc = [0, 1, 2].map(i => ((cum[i] - sA) % P + P) % P);
  const same = (x, y) => Math.min(Math.abs(x - y), P - Math.abs(x - y)) < tol;
  const used = new Set(), pts = [];
  for (const [name, sx] of [['A', 0], ['B', P / 2]]) { const ci = sc.findIndex(v => same(v, sx)); pts.push({ name, angle: ci >= 0 ? triAngle(c, ci) : Math.PI }); if (ci >= 0) used.add(ci); }
  for (let i = 0; i < 3; i++) {
    if (used.has(i)) continue; used.add(i);
    const j = sc.findIndex((v, k) => k !== i && same(v, (P - sc[i]) % P));
    let angle = triAngle(c, i), name = 'v' + (i + 1);
    if (j >= 0) { angle += triAngle(c, j); used.add(j); name += '+v' + (j + 1); } else { angle += Math.PI; name += '+borde'; }
    pts.push({ name, angle });
  }
  return pts.filter(q => Math.abs(2 * Math.PI - q.angle) > 1e-3);
}

